// ── 🏷️ ETIQUETAS ────────────────────────────────────────────
// Dos sub-modos: Producto (anexado desde etiquetas_producto.html, antes
// standalone con su propio login — ya no necesita login ni cliente
// Supabase propio, usa pmDB y la sesión de PanMaestro directo) y Marca
// (etiqueta fija de negocio: logo + redes + QR, no toca Supabase).
// La impresión de ambos modos abre una ventana aparte (mismo patrón que
// docImprimirNota/repComImprimir en reportes.js) en vez de @media print,
// para no chocar con el CSS de impresión de la app principal.

function etMostrar(id) {
  ['et-producto-wrap','et-hoja-wrap','et-lote-wrap','et-fechas-wrap','et-marca-wrap'].forEach(v => {
    const el = document.getElementById(v);
    if (el) el.style.display = v===id ? 'block' : 'none';
  });
  if (id === 'et-marca-wrap') etmkRenderPreview();
  if (id === 'et-fechas-wrap' && typeof etfInit === 'function') etfInit();
}

let etProductos = [];
let etActual = null;

// Refresco ÚNICO de panes y galletas desde Supabase al entrar a Etiquetas.
// Los dos selectores (Producto y Hoja carta) esperan esta misma promesa, así
// ninguno lee G.tiposPan / G.tiposGalleta antes de que terminen de cargar.
let _etRefrescoP = null;
function etRefrescarProductos(forzar) {
  if (!_etRefrescoP || forzar) {
    _etRefrescoP = (async () => {
      try { if (typeof panCargarSb === 'function') await panCargarSb(); } catch (e) { console.warn('[etiquetas] panes', e.message); }
      try { if (typeof gallCargarSb === 'function') await gallCargarSb(); } catch (e) { console.warn('[etiquetas] galletas', e.message); }
    })();
  }
  return _etRefrescoP;
}

async function etCargarCatalogo() {
  const ctc0 = document.getElementById('et-p-contacto');
  if (ctc0) ctc0.textContent = etContactoTexto();
  const sel = document.getElementById('et-producto');
  if (!sel) return;
  try {
    // 1) Esperar a que panes y galletas estén cargados (antes se leían a medias)
    await etRefrescarProductos();
    // 2) Productos de Supabase + los que solo existen en este navegador / Maestros,
    //    sin repetir (por código): así el selector muestra TODOS los panes y galletas.
    let data = [];
    if (pmDB.disponible()) {
      data = await pmDB.get('productos_terminados',
        { activo: true },
        'codigo,nombre,peso_g,precio_full,es_masa_madre'
      ) || [];
    }
    const enSb = new Set(data.map(d => d.codigo));
    const esGalleta = new Set((G.tiposGalleta || []).map(p => p.id));
    const sinSb = [...(G.tiposPan || []), ...(G.tiposGalleta || [])].filter(p => !enSb.has(p.id));
    sinSb.forEach(p => data.push({ codigo: p.id, nombre: p.nombre, peso_g: p.peso || null, precio_full: p.precio || 0, es_masa_madre: false }));
    // 3) Agrupar (Panes / Galletas / Otros) y ordenar alfabético dentro de cada grupo.
    //    etProductos queda en el MISMO orden que se muestra, porque el value del
    //    <option> es la posición en este arreglo.
    const grupos = [['Panes', []], ['Galletas', []], ['Otros', []]];
    const enPan = new Set((G.tiposPan || []).map(p => p.id));
    data.forEach(p => {
      if (esGalleta.has(p.codigo)) grupos[1][1].push(p);
      else if (enPan.has(p.codigo) || !esGalleta.size) grupos[0][1].push(p);
      else grupos[2][1].push(p);
    });
    etProductos = [];
    let html = '<option value="">Seleccioná un producto…</option>';
    grupos.forEach(([titulo, arr]) => {
      if (!arr.length) return;
      const ord = pmOrdenar(arr, 'nombre');
      html += `<optgroup label="${titulo}">` + ord.map(p => {
        etProductos.push(p);
        return `<option value="${etProductos.length - 1}">${pmEsc(p.nombre)}${p.peso_g ? ' — ' + pmEsc(p.peso_g) + ' g' : ''}</option>`;
      }).join('') + '</optgroup>';
    });
    sel.innerHTML = html;
    etActual = null;
  } catch(e) {
    sel.innerHTML = '<option>Error cargando catálogo</option>';
    pmToast('Error al cargar catálogo: ' + e.message, 'err');
  }
}

function etSeleccionar(idx) {
  if (idx === '') { etActual = null; document.getElementById('et-btn-imprimir').disabled = true; document.getElementById('et-btn-imprimir-sp').disabled = true; return; }
  etActual = etProductos[Number(idx)];
  if (!etActual) return;
  document.getElementById('et-peso').value   = etActual.peso_g ?? '';
  document.getElementById('et-precio').value = etActual.precio_full ?? '';
  etActualizarPreview();
  document.getElementById('et-btn-imprimir').disabled = false;
  document.getElementById('et-btn-imprimir-sp').disabled = false;
}

function etActualizarPreview() {
  const ctc = document.getElementById('et-p-contacto');
  if (ctc) ctc.textContent = etContactoTexto();
  const nombre = etActual ? pmNombreSinPeso(etActual.nombre) : '—';
  const pesoVal   = document.getElementById('et-peso').value;
  const precioVal = document.getElementById('et-precio').value;
  const peso   = pesoVal ? `${pesoVal} g` : '—';
  const precio = precioVal ? `₡${Number(precioVal).toLocaleString('es-CR')}` : '—';
  const esMM   = etActual ? !!etActual.es_masa_madre : false;

  document.getElementById('et-p-nombre').textContent = nombre;
  document.getElementById('et-p-peso').textContent   = peso;
  document.getElementById('et-p-precio').textContent = precio;

  const badge = document.getElementById('et-mm-badge');
  badge.classList.toggle('off', !esMM);

  const preview = document.getElementById('et-preview');
  let mmEl = preview.querySelector('.et-mm');
  if (esMM) {
    if (!mmEl) {
      mmEl = document.createElement('div');
      mmEl.className = 'et-mm';
      mmEl.textContent = 'MASA MADRE';
      preview.querySelector('.et-fila').appendChild(mmEl);
    }
  } else if (mmEl) {
    mmEl.remove();
  }
}

// CSS y HTML de UNA etiqueta de producto (7×4 cm). Los usan Producto y En lote.
const ET_CSS = `
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif}
    .label{width:7cm;height:4cm;border:2px solid #000;padding:0.3cm;display:flex;flex-direction:column;justify-content:space-between;background:#fff;page-break-after:always}
    .label:last-child{page-break-after:auto}
    .nombre{font-size:22px;font-weight:600;line-height:1.15}
    .fila{display:flex;gap:0.25cm;align-items:center}
    .campo{border:1px solid #000;border-radius:4px;padding:0.12cm 0.25cm;flex:1}
    .campo .k{font-size:9px;color:#555}
    .campo .v{font-size:15px;font-weight:600}
    .contacto{font-size:7.5px;color:#333;text-align:center;white-space:nowrap}
    .mm{border:2px solid #000;border-radius:20px;padding:0.1cm 0.3cm;font-size:11px;font-weight:700;text-align:center;white-space:nowrap}
    @page{size:7cm 4cm;margin:0}
  `;

// sinPrecio=true: misma etiqueta 7×4 pero sin el campo de precio (el peso ocupa todo el ancho).
function etEtiquetaHtml(p, pesoVal, precioVal, sinPrecio) {
  const peso   = pesoVal ? `${pesoVal} g` : '';
  const precio = precioVal ? `₡${Number(precioVal).toLocaleString('es-CR')}` : '';
  const esMM   = !!p.es_masa_madre;
  return `
    <div class="label">
      <div class="nombre">${pmEsc(pmNombreSinPeso(p.nombre))}</div>
      <div class="fila">
        <div class="campo"><div class="k">peso</div><div class="v">${peso}</div></div>
        ${sinPrecio ? '' : `<div class="campo"><div class="k">precio</div><div class="v">${precio}</div></div>`}
        ${esMM ? '<div class="mm">MASA MADRE</div>' : ''}
      </div>
      <div class="contacto">${pmEsc(etContactoTexto())}</div>
    </div>`;
}

function etImprimir(sinPrecio) {
  if (!etActual) return;
  const cantidad = Math.max(1, parseInt(document.getElementById('et-cantidad').value) || 1);
  const pesoVal   = document.getElementById('et-peso').value;
  const precioVal = document.getElementById('et-precio').value;

  const unaEtiqueta = etEtiquetaHtml(etActual, pesoVal, precioVal, sinPrecio === true);

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head>
    <meta charset="UTF-8">
    <title>Etiquetas — ${pmEsc(pmNombreSinPeso(etActual.nombre))}</title>
    <style>${ET_CSS}</style>
  </head><body>${unaEtiqueta.repeat(cantidad)}<script>window.onload=()=>{window.print();}<\/script></body></html>`);
  win.document.close();
}

// ── 🏷️ ETIQUETAS DE MARCA ──────────────────────────────────
// Etiqueta fija (no varía por producto): logo + nombre + redes + QR.
// El QR es una vCard (nombre + telefono/WhatsApp + ubicacion) - al
// escanearla el celular ofrece guardar el contacto directo. Datos hoy
// fijos en el codigo; si mas adelante se conecta a una pagina web o a
// Supabase, solo cambia ETMK_DATOS/etmkVcard(), no el layout.

const ETMK_LOGO = 'data:image/png;base64,';  // sello oficial PanMaestro (logo_panmaestro.png, 400px)

const ETMK_DATOS = {
  nombre: 'PanMaestro',
  telefono: '+50670565587',
  whatsapp: '7056 5587',
  instagram: 'panmaestro.cr',
  ubicacion: 'San Joaquin de Flores, Costa Rica',
  redes: [
    { icono: 'i', label: 'Instagram @panmaestro.cr' },
    { icono: 'w', label: 'WhatsApp 7056 5587' }
  ]
};

// Contacto que va SIEMPRE en todas las etiquetas (producto, hoja carta y marca)
function etContactoLineas() {
  return ['Instagram @' + ETMK_DATOS.instagram, 'WhatsApp ' + ETMK_DATOS.whatsapp];
}
function etContactoTexto() { return etContactoLineas().join(' · '); }

function etmkVcard() {
  return [
    'BEGIN:VCARD',
    'VERSION:3.0',
    `FN:${ETMK_DATOS.nombre}`,
    `ORG:${ETMK_DATOS.nombre}`,
    `TEL;TYPE=CELL:${ETMK_DATOS.telefono}`,
    `URL:https://instagram.com/${ETMK_DATOS.instagram}`,
    `ADR:;;${ETMK_DATOS.ubicacion};;;;`,
    'END:VCARD'
  ].join('\n');
}

function etmkRedesHTML() {
  return ETMK_DATOS.redes.map(r =>
    `<span class="et-mk-red"><b>${pmEsc(r.icono)}</b> ${pmEsc(r.label)}</span>`
  ).join('');
}

function etmkRenderPreview() {
  const logoImg = document.getElementById('et-mk-logo-img');
  const nombreEl = document.getElementById('et-mk-nombre');
  const redesEl = document.getElementById('et-mk-redes');
  if (logoImg) logoImg.src = ETMK_LOGO;
  if (nombreEl) nombreEl.textContent = ETMK_DATOS.nombre;
  if (redesEl) redesEl.innerHTML = etmkRedesHTML();

  const cont = document.getElementById('et-mk-qr-preview');
  if (!cont || typeof QRCode === 'undefined') return;
  cont.innerHTML = '';
  new QRCode(cont, { text: etmkVcard(), width: 96, height: 96, correctLevel: QRCode.CorrectLevel.M });
}

function etmkGenerarQRDataURL() {
  if (typeof QRCode === 'undefined') return '';
  const tmp = document.createElement('div');
  tmp.style.cssText = 'position:absolute;left:-9999px;top:-9999px';
  document.body.appendChild(tmp);
  new QRCode(tmp, { text: etmkVcard(), width: 260, height: 260, correctLevel: QRCode.CorrectLevel.M });
  const canvas = tmp.querySelector('canvas');
  const dataUrl = canvas ? canvas.toDataURL('image/png') : '';
  document.body.removeChild(tmp);
  return dataUrl;
}

function etmkImprimir() {
  const cantidad = Math.max(1, parseInt(document.getElementById('et-mk-cantidad').value) || 1);
  const qrDataUrl = etmkGenerarQRDataURL();
  if (!qrDataUrl) { pmToast('No se pudo generar el QR, recargá la página e intentá de nuevo', 'err'); return; }

  const CSS = `
    *{box-sizing:border-box;margin:0;padding:0}
    html,body{width:4cm}
    body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif}
    .label{width:4cm;height:7cm;padding:0.25cm;display:flex;flex-direction:column;align-items:center;justify-content:space-evenly;background:#fff;overflow:hidden;page-break-after:always}
    .label:last-child{page-break-after:auto}
    .logo{width:1.8cm;height:1.8cm;border-radius:50%;object-fit:cover;flex-shrink:0}
    .nombre{font-size:12px;font-weight:600;text-align:center;line-height:1.2}
    .redes{display:flex;flex-direction:column;align-items:center;gap:0.08cm;font-size:9px;color:#333}
    .qr{width:2.3cm;height:2.3cm;flex-shrink:0}
    @page{size:4cm 7cm;margin:0}
  `;

  const unaEtiqueta = `
    <div class="label">
      <img class="logo" src="${ETMK_LOGO}">
      <div class="nombre">${pmEsc(ETMK_DATOS.nombre)}</div>
      <div class="redes">${etmkRedesHTML()}</div>
      <img class="qr" src="${qrDataUrl}">
    </div>`;

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head>
    <meta charset="UTF-8">
    <title>Etiqueta de marca -- ${pmEsc(ETMK_DATOS.nombre)}</title>
    <style>${CSS}</style>
  </head><body>${unaEtiqueta.repeat(cantidad)}<script>
    window.onload = () => { setTimeout(() => window.print(), 150); };
  <\/script></body></html>`);
  win.document.close();
}

